//! Generates the ModelExpress Kubernetes CRDs from their Rust definitions.

use kube::CustomResourceExt;
use modelexpress_server::p2p::k8s_types::ModelMetadata;
use modelexpress_server::registry::k8s_types::ModelCacheEntry;

const HEADER: &str = "# SPDX-FileCopyrightText: Copyright (c) 2025-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.\n\
# SPDX-License-Identifier: Apache-2.0\n\
#\n\
# Generated by `cargo run -p modelexpress-server --bin crdgen`. Do not edit manually.\n";

fn generate_crds() -> anyhow::Result<String> {
    Ok(format!(
        "{HEADER}{}---\n{}",
        serde_yaml::to_string(&ModelMetadata::crd())?,
        serde_yaml::to_string(&ModelCacheEntry::crd())?
    ))
}

fn main() -> anyhow::Result<()> {
    print!("{}", generate_crds()?);
    Ok(())
}

#[cfg(test)]
#[allow(clippy::expect_used)]
mod tests {
    use super::*;

    #[test]
    fn generated_crds_match_checked_in_manifests() {
        let generated = generate_crds().expect("CRDs should serialize");
        assert_eq!(generated, include_str!("../../../examples/crds.yaml"));
    }

    #[test]
    fn main_generates_crds() {
        main().expect("CRDs should print");
    }
}
